89	    "Member",
90	    input.memberId,
91	  );
92	  assertCan(actor, "member:remove", memberResource(member));
93	
94	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
95	
96	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
97	
98	  await emit("member.removed", {
99	    ...actorEnvelope(actor),
100	    memberId: removed.id,
101	    userId: removed.userId,
102	  });
103	
104	  return removed;
105	}
