124	 * without an owner. Exported because both the demote and the remove path need
125	 * it, and the invariant must not be stated twice.
126	 */
127	export async function assertLastOwnerRetained(
128	  orgId: OrgId,
129	  memberId: MemberId,
130	  nextRole: Role,
131	): Promise<void> {
132	  if (nextRole === "owner") return;
133	
134	  const member = await memberRepo.findMemberById(orgId, memberId);
135	  if (!member || member.role !== "owner") return;
136	
137	  const page = await memberRepo.listMembers({
138	    orgId,
139	    role: "owner",
140	    limit: OWNER_SCAN_LIMIT,
141	    cursor: null,
142	  });
143	
144	  const remaining = page.items.filter((row) => row.id !== memberId);
145	  if (remaining.length === 0) {
146	    throw new Error(
147	      "An organization must keep at least one owner; transfer ownership first",
148	    );
149	  }
